#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    vector<string> basket;
    string s = "{word}";

    basket.push_back(s);
    basket.push_back(move(s));

    cout << basket[0] << " / " << basket[1] << endl;
    cout << s.size() << endl;
    return 0;
}
